emu.addMemoryCallback(function(_,v)
 if not entered or done then return end
 local st=emu.getState();local pc=st['cpu.pc'];local owner=bank(pc);local q={start=stamp(),page=v,source=bytes(v*256,emu.memType.nesDebug),writes=0};strictDmaPending=q
 dmaBus:write(json({kind='DMA-start',stamp=q.start,pc=pc,bank=owner,source_hex=(q.source:gsub('.',function(x)return string.format('%02x',x:byte())end))})..'\n');dmaBus:flush()
 assert(safeOam(q.start),'Actual DMA starts inside vblank or disabled rendering')
 assert(emu.read(pc,emu.memType.nesDebug)==0xa2 and emu.read(pc+1,emu.memType.nesDebug)==1,'Actual DMA next instruction LDX1')
 local finish=pc+2;local key=owner..':'..finish
 if not strictDmaHooks[key]then
  strictDmaHooks[key]=true
  queueReturnSlot(finish,function()
   if not strictDmaPending or bank(finish)~=owner then return end
   local q=strictDmaPending;strictDmaPending=nil;local hardware=bytes(0,emu.memType.nesSpriteRam);local endState=stamp()
   dmaBus:write(json({kind='DMA-complete',stamp=endState,source_exact=hardware==q.source,data_writes=q.writes,hardware_hex=(hardware:gsub('.',function(x)return string.format('%02x',x:byte())end))})..'\n');dmaBus:flush()
   assert(q.writes==256,'Actual completed DMA has256 data writes')
   assert(hardware==q.source,'Actual completed DMA hardware equals complete source page')
   assert(safeOam(endState),'Actual DMA completes inside vblank or disabled rendering')
   strictDMA=strictDMA+1
